<script lang="ts">
 import {planBlend} from '@vinea/domain';
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();
 function estimate(recipe:Record<string,any>){try{const snapshot=recipe.snapshot?.positions??[];return planBlend(recipe.components.map((c:any)=>{const p=model.positions.find(p=>p.id===c.position_id),lot=model.lots.find(l=>l.id===p?.lot_id),frozen=Array.isArray(snapshot)?snapshot.find((p:any)=>p.id===c.position_id):null;const superseded=new Set(model.analyses.map(a=>a.supersedes).filter(Boolean));const measurements=frozen?.analyses??model.analyses;const replaced=new Set(measurements.map((a:any)=>a.supersedes).filter(Boolean));const a=[...measurements].sort((a:any,b:any)=>Date.parse(b.measured_at)-Date.parse(a.measured_at)).find((a:any)=>(frozen||a.lot_id===lot?.id)&&a.parameter==='alcohol'&&a.quality==='measured'&&!replaced.has(a.id));return {id:c.position_id,volume:c.quantity_l,available:c.quantity_l,cost:frozen?.cost_per_l??lot?.cost_per_l??'0',alcohol:a?.value??null,unit:a?.unit??null,method:a?.method??null,blocked:false};}));}catch{return null;}}
</script>
<section class="card"><h2>{t('compareVariants')}</h2><p class="muted">{t('comparisonHint')}</p>{#each model.briefs.filter(b=>b.reference_lot_id) as brief}{@const reference=model.lots.find(l=>l.id===brief.reference_lot_id)}<article><h3>{model.projects.find(p=>p.id===brief.project_id)?.name} · {t('reference_lot_id')}</h3><p>{brief.style}</p>{#if reference}<p>{reference.code} · {reference.name} · {reference.vintage}</p>{#each ['alcohol','sugar','acidity','ph','free_so2'] as parameter}{@const a=model.analyses.find(a=>a.lot_id===reference.id&&a.parameter===parameter&&a.quality==='measured'&&!model.analyses.some(n=>n.supersedes===a.id))}<p>{parameter==='ph'?'pH':t(parameter)} · {a?.value??'—'} {a?.unit??''} · {a?.method??''} · {a?.measured_at??''}</p>{/each}{/if}</article>{/each}<div class="variants">{#each model.recipes as recipe}{@const result=estimate(recipe)}<article><h3>{recipe.name} · v{recipe.revision}</h3><p>{recipe.target_l} L · {t(recipe.state)}</p>{#if result}<p>{result.cost} € · {result.costPerLiter} €/L</p><p>{t('alcohol')} ≈ {result.alcohol??t('missing')}</p>{/if}<p class="muted">{t('ph')}</p><ul>{#each recipe.components as c}<li>{model.positions.find(p=>p.id===c.position_id)?.lot_code??c.position_id} · {c.quantity_l} L</li>{/each}</ul>{#each model.trials.filter(trial=>trial.recipe_id===recipe.id) as trial}<p>{trial.blind_code} · {model.evaluations.filter(e=>e.trial_id===trial.id).map(e=>e.score).join(' / ')||t('empty')}</p>{/each}</article>{/each}</div></section>
<style>.variants{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:15px}article{border:1px solid #e1e7de;border-radius:8px;padding:16px}ul{padding-left:18px}</style>
